WITH benchmark AS (SELECT b.volume FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='贵州茅台' AND b.bizdate='2026-04-14') SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b CROSS JOIN benchmark AS q WHERE b.mktcode=1 AND b.bizdate='2026-04-14' AND b.volume>q.volume;
